def log_fix(sigma, gamma, n):
    # Kimura fixation probability (log) for a variant with selection coefficient sigma in a pop of size n
    x = gamma * sigma
    if np.isclose(x, 0): return -np.log(n)
    if x > 0: return np.log1p(-np.exp(-x)) - np.log1p(-np.exp(-n * x))
    return (n - 1) * x + np.log1p(-np.exp(x)) - np.log1p(-np.exp(n * x))

def step_tables(kds, gamma):
    # per-genotype log fixation rate and destination index for each single forward mutation
    idx = {g: i for i, g in enumerate(genotypes)}
    log_rate = np.full((len(genotypes), n_sites), -np.inf)
    nxt = np.full((len(genotypes), n_sites), -1, dtype=np.int64)
    for i, g in enumerate(genotypes):
        for p in range(n_sites):
            if g[p] != "G": continue
            j = idx.get(g[:p] + "M" + g[p + 1:])
            if j is not None:
                log_rate[i, p] = log_fix(kds[j] - kds[i], gamma, n_pop)
                nxt[i, p] = j
    return log_rate, nxt

def simulate(log_rate, nxt, kds, rng):
    # Gumbel-max sampling of n_samples fixation trajectories; record acquisition order and downhill steps
    start = genotypes.index("G" * n_sites)
    state = np.full(n_samples, start, dtype=np.int64)
    orders = np.full((n_samples, n_sites), -1, dtype=np.int64)
    is_del = np.zeros((n_samples, n_sites), dtype=bool)
    for k in range(n_sites):
        row = log_rate[state]
        active = np.isfinite(row).any(1)
        gumbel = -np.log(-np.log(rng.random((n_samples, n_sites)) + 1e-300) + 1e-300)
        pos = np.where(active, (row + gumbel).argmax(1), -1)
        orders[:, k] = pos
        nx = nxt[state, np.where(active, pos, 0)]
        is_del[:, k] = active & ((kds[np.where(nx >= 0, nx, state)] - kds[state]) < 0)
        state = np.where(active & (nx >= 0), nx, state)
    return orders, is_del

def occupancy(orders, is_del):
    # step x mutation occupancy: p_all over all completed walks, p_keep over strictly-uphill survivors
    keep = ~(orders == -1).any(1)
    ordr, dele = orders[keep], is_del[keep]
    n = int(keep.sum())
    p_all = np.zeros((n_sites, n_sites))
    p_keep = np.zeros((n_sites, n_sites))
    survived = np.cumprod(~dele, axis=1).astype(bool)   # still uphill through step k
    for k in range(n_sites):
        p_all[k] = np.bincount(ordr[:, k], minlength=n_sites) / n
        if survived[:, k].any():
            p_keep[k] = np.bincount(ordr[:, k][survived[:, k]], minlength=n_sites) / n
    return p_all, p_keep

def traj_panel_data(rng):
    # occupancy for every complex at additive (order 1) and full (best order) landscapes
    out = {}
    for ab in [a for row in row_abs for a in row]:
        labels, _ = site_meta(meta_files[ab])
        for ag in antigens:
            intercept, terms, best_order, _ = load_params(param_files[(ab, ag)])
            cell = {"labels": labels, "best": best_order, "orders": {}}
            for order in {1, best_order}:
                kds = kds_at(intercept, terms, order)
                log_rate, nxt = step_tables(kds, gamma_traj)
                cell["orders"][order] = occupancy(*simulate(log_rate, nxt, kds, rng))
            out[(ab, ag)] = cell
    return out
